import puppeteer from 'puppeteer';
import fs from 'fs';

const cwd = process.cwd();
const b = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox', '--disable-dev-shm-usage'] });
const p = await b.newPage();
const errors = [];
p.on('pageerror', e => errors.push('pageerror: ' + e.message));
p.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

await p.goto('file:///' + cwd + '/index.html', { waitUntil: 'networkidle0' });

const counts = await p.evaluate(() => ({
  panes: document.querySelectorAll('#body > .pane').length,
  tabs: document.querySelectorAll('.tab').length,
  lists: document.querySelectorAll('.list').length,
  items: document.querySelectorAll('.pane[data-step-pane] .item').length,
}));
console.log('COUNTS', JSON.stringify(counts));
if (counts.items !== 96) throw new Error('expected 96 items, got ' + counts.items);
if (counts.lists !== 24) throw new Error('expected 24 lists');
if (counts.tabs !== 8) throw new Error('expected 8 tabs');

// initial state word order per question
const initial = await p.evaluate(() =>
  Array.from(document.querySelectorAll('#body .pane[data-step-pane]')).map(pn =>
    Array.from(pn.querySelectorAll('.list')).map(ul =>
      Array.from(ul.querySelectorAll('.item')).map(li => li.dataset.word)
    )
  )
);
const flat = initial.flat(2);
console.log('TOTAL WORDS', flat.length, 'UNIQUE', new Set(flat).size);
if (flat.length !== 96) throw new Error('word count wrong');

// ---- test drag: move first item of step0/list0 to the end
const listSel = '#tab1 .list[data-q="0"]';
const beforeOrder = await p.evaluate(sel => Array.from(document.querySelector(sel).children).map(li => li.dataset.word), listSel);
const handle = await p.$(listSel + ' > .item');
const box = await handle.boundingBox();
const lastHandle = await p.$(listSel + ' > .item:nth-child(4)');
const lbox = await lastHandle.boundingBox();
const x = box.x + box.width / 2;
await p.mouse.move(x, box.y + box.height / 2);
await p.mouse.down();
await p.mouse.move(x, (box.y + lbox.y + lbox.height) / 2, { steps: 3 });
await p.mouse.move(x, lbox.y + lbox.height - 4, { steps: 3 });
await p.mouse.up();
await new Promise(r => setTimeout(r, 120));
const afterOrder = await p.evaluate(sel => Array.from(document.querySelector(sel).children).map(li => li.dataset.word), listSel);
console.log('DRAG before', JSON.stringify(beforeOrder));
console.log('DRAG after ', JSON.stringify(afterOrder));
if (JSON.stringify(beforeOrder) === JSON.stringify(afterOrder)) throw new Error('drag did not reorder');
if (afterOrder[0] !== beforeOrder[0] || afterOrder[afterOrder.length - 1] !== beforeOrder[0])
  throw new Error('drag expected to move first item to last');

// navigate to step 2
await p.click('#tabs .tab[data-step-btn="2"]');
await new Promise(r => setTimeout(r, 120));
const active2 = await p.evaluate(() => document.querySelector('#body .pane.is-active').id);
if (active2 !== 'tab3') throw new Error('step nav failed, active=' + active2);

// next/prev buttons
await p.click('#btnPrev');
const activeAfter = await p.evaluate(() => document.querySelector('#body .pane.is-active').id);
if (activeAfter !== 'tab2') throw new Error('btnPrev failed');

// go to last step
await p.evaluate(() => { document.querySelector('#tabs .tab[data-step-btn="7"]').click(); });
await new Promise(r => setTimeout(r, 80));
const finishVisible = await p.evaluate(() => !document.getElementById('btnFinish').hidden);
if (!finishVisible) throw new Error('finish button not visible on step 7');
const nextHidden = await p.evaluate(() => document.getElementById('btnNext').hidden);
if (!nextHidden) throw new Error('next button should be hidden on step 7');

// finish -> result
await p.click('#btnFinish');
await new Promise(r => setTimeout(r, 150));
const resultVisible = await p.evaluate(() => document.getElementById('tabResult').classList.contains('is-active'));
if (!resultVisible) throw new Error('result pane not active after finish');
const scores = await p.evaluate(() => Array.from(document.querySelectorAll('.result-card')).map(c => c.dataset.letter + '=' + c.querySelector('.score').textContent));
console.log('SCORES', JSON.stringify(scores));

// reset works
await p.click('.result-actions .btn');
await new Promise(r => setTimeout(r, 120));
const activeReset = await p.evaluate(() => document.querySelector('#body .pane.is-active').id);
if (activeReset !== 'tab1') throw new Error('reset failed, active=' + activeReset);

// Esc resets
await p.keyboard.press('Escape');
await new Promise(r => setTimeout(r, 60));

console.log('ERRORS', JSON.stringify(errors));
console.log('ALL CHECKS PASSED');
await b.close();

